(function(){"use strict";var COURSE_URL="/baza";var PERSONAL_ASSESSMENT_URL="/anketaplan";var TELEGRAM_TEST_URL="[TELEGRAM_TEST_URL]";var SHOW_TELEGRAM_TEST_LINK=false;var root=document.getElementById("egGuideRoot");if(!root){return;}
function track(ev){try{window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:"eg_guide",eg_action:ev});}catch(e){}}
root.addEventListener("click",function(e){var t=e.target.closest("[data-ev]");if(t){track(t.getAttribute("data-ev"));}});track("guide_open");var pf=document.getElementById("egProgFill");function updProg(){if(!pf) return;var rect=root.getBoundingClientRect();var total=root.offsetHeight - window.innerHeight;var passed=Math.min(Math.max(-rect.top,0),total>0?total:0);pf.style.width=(total>0?passed/total*100:0)+"%";}
var progTicking=false;function onScrollProg(){if(!progTicking){requestAnimationFrame(function(){updProg();progTicking=false;});progTicking=true;}}
window.addEventListener("scroll",onScrollProg,{passive:true});window.addEventListener("resize",onScrollProg);updProg();root.addEventListener("click",function(e){var a=e.target.closest('a[href^="#"]');if(!a){return;}
var id=a.getAttribute("href").slice(1);if(!id){return;}
var el=document.getElementById(id);if(el){e.preventDefault();try{el.scrollIntoView({behavior:"smooth",block:"start"});}catch(_){el.scrollIntoView();}}});function initVideo(id,ev){var box=document.getElementById(id);if(!box){return;}
var poster=box.querySelector(".poster");function play(){var url=box.getAttribute("data-embed")||"";if(!url||url.indexOf("[")===0){alert("Видео скоро появится.");return;}
var sep=url.indexOf("?")>-1?"&":"?";var iframe=document.createElement("iframe");iframe.setAttribute("allow","autoplay; fullscreen; picture-in-picture; encrypted-media");iframe.setAttribute("allowfullscreen","");iframe.src=url + sep + "autoplay=1";box.appendChild(iframe);box.classList.add("playing");track(ev);}
poster.addEventListener("click",play);poster.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();play();}});}
initVideo("egWelcome","welcome_video_play");var QUESTIONS=[{t:"Дыхание",instr:"Сядь или ляг удобно, положи ладони на нижние рёбра и сделай несколько спокойных вдохов через нос.",q:"Получается дышать спокойно, не поднимая плечи и не напрягая шею?"},{t:"Подъём рук",instr:"Встань спиной к стене и спокойно подними руки вверх.",q:"Получается поднять руки без сильного прогиба в пояснице и напряжения в шее?"},{t:"Наклон",instr:"Встань прямо, слегка согни колени и отведи таз назад, словно хочешь коснуться им стены.",q:"Получается выполнить наклон через тазобедренные суставы, сохраняя спокойное дыхание?"},{t:"Приседание",instr:"Выполни медленное неглубокое приседание без веса.",q:"Получается сохранять опору всей стопой и контролировать положение коленей?"},{t:"Баланс",instr:"Встань на одну ногу на 20 секунд, затем повтори другой ногой.",q:"Получается сохранять равновесие без сильной разницы между сторонами?"}];var OPTS=[{label:"Да, движение даётся свободно",val:2},{label:"Есть ограничение или разница сторон",val:1},{label:"Не получается или возникает боль",val:0}];var RESULTS=[{score:"0–3 балла",title:"Начни с самых основ",body:"<p>Тебе сейчас важнее не гнать нагрузку, а спокойно вернуть телу дыхание, подвижность и контроль. И это, по-хорошему, приятная новость — с базы обычно идут самые заметные сдвиги в самочувствии.</p><p>Двигайся мягко, без спешки. Первые шаги простые. С них и начинается вся свобода в теле.</p>",prio:"Дыхание и мягкое возвращение подвижности. Освой их спокойно, а нагрузку добавляй уже потом.",avoid:"Не бросайся в тяжёлые тренировки и резкие амплитуды. Сейчас с них будет больше напряжения, чем толку."},{score:"4–7 баллов",title:"База есть, но отдельные звенья требуют внимания",body:"<p>Тренироваться ты уже можешь. Но какие-то участки, похоже, тянут на себе чуть больше положенного или заметно разнятся по сторонам. Как раз это и стоит выровнять.</p><p>Подтяни слабые звенья, добавь контроль — и тренировки пойдут ровнее, без привычных напоминаний о себе.</p>",prio:"Найти, где движение зажато или где стороны спорят между собой, и вернуть туда контроль и подвижность.",avoid:"Не закрывай глаза на разницу сторон и не грузи сверху ограничения — так закрепляется старая компенсация."},{score:"8–10 баллов",title:"Хорошая исходная база",body:"<p>База в порядке. Дальше интереснее — соединить это качество движения с силой, координацией и серьёзной нагрузкой.</p><p>Тебе зайдёт работа над устойчивостью движения и грамотная прогрессия, чтобы расти дальше и не терять технику.</p>",prio:"Закреплять качество движения силой и осмысленной прогрессией.",avoid:"Не гонись за объёмом ради объёма. На твоём уровне решает техника, а не лишние повторы."}];function bucket(total){if(total<=3) return 0;if(total<=7) return 1;return 2;}
var beforeScore=null;function makeTest(cfg){var qbox=document.getElementById(cfg.qbox),prog=document.getElementById(cfg.prog),bar=document.getElementById(cfg.bar),back=document.getElementById(cfg.back),testEl=document.getElementById(cfg.test);if(!qbox||!back){return;}
var answers=[null,null,null,null,null],cur=0,started=false;function renderQ(){var d=QUESTIONS[cur];var html='<div class="qtitle">'+d.t+'</div>';html+='<div class="qtext">'+d.q+'</div>';html+='<div class="qinstr">'+d.instr+'</div>';html+='<div class="opts">';OPTS.forEach(function(o){var sel=answers[cur]===o.val?" sel":"";html+='<button type="button" class="opt'+sel+'" data-val="'+o.val+'" aria-label="'+o.label+'"><span class="rd"></span><span>'+o.label+'</span></button>';});html+='</div>';qbox.innerHTML=html;prog.textContent="Вопрос "+(cur+1)+" из 5";bar.style.width=((cur+1)/5*100)+"%";back.style.visibility=cur>0?"visible":"hidden";if(!started){started=true;track(cfg.ev+"_start");}
track(cfg.ev+"_question_"+(cur+1));qbox.querySelectorAll(".opt").forEach(function(btn){btn.addEventListener("click",function(){answers[cur]=parseInt(btn.getAttribute("data-val"),10);qbox.querySelectorAll(".opt").forEach(function(b){b.classList.remove("sel");});btn.classList.add("sel");setTimeout(next,240);});});}
function next(){if(cur<4){cur++;renderQ();}
else {var total=answers.reduce(function(a,b){return a +(b||0);},0);testEl.style.display="none";track(cfg.ev+"_complete");cfg.onDone(total);}}
back.addEventListener("click",function(){if(cur>0){cur--;renderQ();}});renderQ();}
makeTest({qbox:"egQbox",prog:"egProg",bar:"egBarFill",back:"egBack",test:"egTest",ev:"selfcheck",onDone:function(total){beforeScore=total;var b=bucket(total),r=RESULTS[b];document.getElementById("egScoreLine").textContent="Твой результат · "+total+" из 10 · "+r.score;document.getElementById("egResTitle").textContent=r.title;document.getElementById("egResBody").innerHTML=r.body;document.getElementById("egResPrio").textContent=r.prio;document.getElementById("egResAvoid").textContent=r.avoid;var tg=document.getElementById("egTgLink"),tga=document.getElementById("egTgA");if(SHOW_TELEGRAM_TEST_LINK&&TELEGRAM_TEST_URL&&TELEGRAM_TEST_URL.indexOf("[")!==0){tga.href=TELEGRAM_TEST_URL;tg.style.display="block";}
else {tg.style.display="none";}
var resultEl=document.getElementById("egResult");resultEl.classList.add("on");track(b===0?"selfcheck_result_low":(b===1?"selfcheck_result_medium":"selfcheck_result_high"));try{resultEl.scrollIntoView({behavior:"smooth",block:"start"});}catch(e){resultEl.scrollIntoView();}}});makeTest({qbox:"egQbox2",prog:"egProg2",bar:"egBarFill2",back:"egBack2",test:"egTest2",ev:"retest",onDone:function(total){var scoreEl=document.getElementById("egReScore"),titleEl=document.getElementById("egReTitle"),bodyEl=document.getElementById("egReBody"),resultEl=document.getElementById("egRetestResult");var title,body,delta=0;if(beforeScore===null){scoreEl.textContent="Результат · "+total+" из 10";title="Твоя точка старта";body="<p>Похоже, диагностику до зарядки ты пропустил — ничего страшного. Теперь у тебя есть ориентир. Сделай зарядку и пройди проверку ещё раз, чтобы увидеть разницу.</p>";} else {delta=total - beforeScore;scoreEl.textContent="Было: "+beforeScore+" из 10  →  Стало: "+total+" из 10";if(delta>=2){title="Заметный сдвиг за 10 минут";body="<p>Ты сам это почувствовал: движение стало свободнее. Это и есть двигательная база в действии — тело быстро отзывается, когда с ним работают по порядку.</p><p>Представь, что даёт не одна зарядка, а выстроенная система.</p>";} else if(delta>=1){title="Первые изменения пошли";body="<p>Даже небольшой сдвиг за одну короткую практику — хороший знак. Тело откликается. При регулярной работе такие изменения закрепляются и растут.</p>";} else if(delta===0){title="Тело только знакомится с движением";body="<p>Если пока без заметных изменений — это нормально. За одну зарядку фундамент не строится. Важно, что ты уже начал и теперь знаешь свою точку старта.</p>";} else {title="Прислушайся к телу";body="<p>Иногда после непривычной работы тело реагирует по-своему — это нормально. Двигательная база строится спокойно и постепенно, по чуть-чуть и регулярно.</p>";}}
titleEl.textContent=title;bodyEl.innerHTML=body;resultEl.classList.add("on");track("retest_complete");track(beforeScore===null?"retest_no_baseline":(delta>=1?"retest_improved":"retest_same"));try{resultEl.scrollIntoView({behavior:"smooth",block:"start"});}catch(e){resultEl.scrollIntoView();}}});(function(){var wrap=document.getElementById("egRecog");var out=document.getElementById("egRecogCount");if(!wrap||!out){return;}
var cards=wrap.querySelectorAll(".r");var interacted=false;function msg(n){if(n===0){return "";}
var tail=n<=2?"Уже есть с чем работать.":(n<=4?"Ты точно по адресу.":"Тем более стоит дочитать до конца.");return '<b>Узнал себя: '+n+' из 6.</b> '+tail;}
function upd(){out.innerHTML=msg(wrap.querySelectorAll(".r.on").length);}
cards.forEach(function(card){function toggle(){card.classList.toggle("on");if(!interacted){interacted=true;track("recog_interact");}
upd();}
card.addEventListener("click",toggle);card.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();toggle();}});});})();})();
